from h import *
O=[]
O.append(R(6566186,ar=(
"لفائف الدجاج المشوي",
"يملأ صدر الدجاج المشوي والبصل لفائف العشاء اللذيذة هذه. اطهُ الدجاج والبصل على شواية داخلية أو خارجية.",
"2","1 لفّة",
["½ رطل صدور دجاج منزوعة العظم والجلد","¼ ملعقة صغيرة فلفل أسود","½ كوب بصل (مقطّع شرائح بسماكة نحو ¼ بوصة)","¼ كوب صلصة باربكيو بدون سكر مضاف","2 رغيف تورتيلا من دقيق القمح الكامل (8 بوصات)","½ كوب خس (مقطّع شرائح رفيعة)","½ كوب طماطم طازجة (مقطّعة مكعبات)"],
["سخّن شواية الموقد.","أزل أي دهون ظاهرة عن الدجاج وتبّله بالفلفل الأسود.","ضع الدجاج وشرائح البصل على الشواية. اطبخهما 5 دقائق. اقلب الدجاج والبصل واشوِهما 3 دقائق. اسكب صلصة الباربكيو بالملعقة فوق الدجاج والبصل واشوِهما دقيقتين. يجب أن يصل مقياس حرارة اللحوم إلى 165 درجة فهرنهايت (75 درجة مئوية) للدلالة على أن الدجاج تمام النضج. انقله إلى طبق. فتّت الدجاج باستخدام شوكتين. افصل البصل إلى حلقات.","في الأثناء، لفّ التورتيلا بورق الألمنيوم وضعها على الشواية 3 دقائق لتسخن جيدًا. املأ كل رغيف تورتيلا بقليل من الدجاج والبصل ولفّه على شكل لفّة.","وزّع الخس على طبقين وضع فوقه الطماطم المقطّعة. قدّمها."],[],[])))
O.append(R(6566587,ar=(
"بطاطس مهروسة بالأعشاب وزيت الزيتون",
"الإصابة بالسكري لا تعني أن عليك الاستغناء عن الأطعمة النشوية تمامًا. يمكنك الاستمتاع بها بالكميات المناسبة! تستغني وصفة البطاطس المهروسة هذه عن الزبدة والكريمة وتستخدم مكوّنات أكثر صحة لتحصل على طبق لذيذ ومليء بالنكهة.",
"6","½ كوب",
["10 حبات بطاطس ذهبية صغيرة كاملة (نحو 1 رطل إجمالًا، مغسولة جيدًا ومقطّعة أرباعًا)","¼ كوب عصير ليمون (طازج العصر)","2 ملعقة كبيرة زيت زيتون بكر ممتاز","¼ كوب كزبرة خضراء طازجة (مفرومة ناعمًا)","¼ كوب شبت طازج (مفروم ناعمًا)","½ ملعقة صغيرة ملح بحري أو ملح كوشر","¼ ملعقة صغيرة فلفل أسود مطحون طازجًا","1 ملعقة كبيرة قشر ليمون مبشور"],
["ضع البطاطس في قدر كبيرة وغطِّها بالماء. اتركها حتى تغلي على نار عالية، ثم خفّض الحرارة إلى متوسطة واطبخها دون غطاء 10–15 دقيقة أو حتى تلين. صفِّها. أضف عصير الليمون وزيت الزيتون، وابدأ بهرسها يدويًا أو بخلاط كهربائي. عندما يصبح الخليط ناعمًا وكريميًا، أضف قشر الليمون المبشور والكزبرة الخضراء والشبت والملح والفلفل وقلّب. قدّمها دافئة."],[],[])))
O.append(R(6567580,
("Huevos al horno con verduras de primavera asadas","Este colorido desayuno en bandeja incluye verduras de primavera asadas y huevos horneados a la perfección para empezar el día con una comida equilibrada y rica en verduras. Lleno de fibra y nutrientes, es una opción que ayuda a mantener estable la glucosa en la sangre (azúcar en la sangre) sin depender de carbohidratos refinados. Ideal para personas con diabetes, es nutritivo y fácil de preparar con anticipación. Es una receta baja en carbohidratos y vegetariana.","4","1 1/2 tazas de verduras asadas, 1 huevo por porción",
["1 taza de espárragos (recortados y cortados en trozos de 1 pulgada)","1 taza de tomates cherry (en mitades)","1 calabacita mediana (en medias lunas)","1 pimiento rojo mediano (en cubos)","1 cebolla morada pequeña (en rodajas finas)","2 dientes de ajo (picados)","2 cucharaditas de aceite de oliva","1 cucharadita de orégano seco","1/2 cucharadita de pimienta negra (molida)","1/4 de cucharadita de sal","1 taza de hojas de espinaca baby","4 huevos grandes","1/4 de taza de albahaca fresca (para decorar)","1 rocío, 0.25 gramos de aceite en aerosol antiadherente"],
["Precaliente el horno a 400° F.","En un tazón grande, mezcle los espárragos, los tomates cherry, la calabacita, el pimiento, la cebolla morada y el ajo.","Rocíe con el aceite de oliva y espolvoree con el orégano seco, la pimienta negra y la sal. Revuelva hasta que las verduras estén cubiertas de manera uniforme.","Rocíe ligeramente una bandeja grande para hornear con aceite en aerosol. Extienda las verduras sazonadas en una sola capa sobre la bandeja. Áselas en el horno precalentado de 15 a 20 minutos, o hasta que estén tiernas y ligeramente caramelizadas.","Saque la bandeja del horno y esparza las espinacas baby sobre las verduras asadas. El calor marchitará ligeramente las espinacas.","Haga cuatro huecos pequeños entre las verduras y casque con cuidado un huevo en cada uno.","Vuelva a colocar la bandeja en el horno y hornee de 7 a 10 minutos más, o hasta que las claras estén firmes y las yemas tengan el punto de cocción que prefiera.","Espolvoree albahaca fresca sobre las verduras y los huevos."],[],[]),
("بيض مخبوز مع خضار الربيع المشوية","فطور ملوّن يُحضَّر على صينية واحدة، يضم خضار الربيع المشوية وبيضًا مخبوزًا بإتقان لبداية متوازنة للنهار تركّز على الخضار. وهو غني بالألياف والعناصر الغذائية، وخيار يساعد على استقرار مستوى الغلوكوز في الدم (سكر الدم) دون الاعتماد على الكربوهيدرات المكررة. مثالي لمرضى السكري، فهو مغذٍّ وسهل التحضير مسبقًا. وهذه وصفة قليلة الكربوهيدرات ونباتية.","4","1½ كوب خضار مشوية، بيضة واحدة لكل حصة",
["1 كوب هليون (مقصوص الأطراف ومقطّع إلى قطع بطول 1 بوصة)","1 كوب طماطم كرزية (مقطّعة نصفين)","1 حبة كوسا متوسطة (مقطّعة على شكل أنصاف أقمار)","1 حبة فلفل رومي أحمر متوسطة (مقطّعة مكعبات)","1 حبة بصل أحمر صغيرة (مقطّعة شرائح رفيعة)","2 فص ثوم (مفروم)","2 ملعقة صغيرة زيت زيتون","1 ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة فلفل أسود (مطحون)","¼ ملعقة صغيرة ملح","1 كوب أوراق سبانخ صغيرة","4 بيضات كبيرة","¼ كوب ريحان طازج (للتزيين)","1 بخّة (0.25 غرام) بخاخ طهي غير لاصق"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (200° مئوية).","في وعاء خلط كبير، اخلط الهليون والطماطم الكرزية والكوسا والفلفل الرومي والبصل الأحمر والثوم.","رشّ زيت الزيتون وأضف الأوريجانو المجفف والفلفل الأسود والملح. قلّب حتى تتغلف الخضار بالتساوي.","ادهن صينية خَبز كبيرة بخفة ببخاخ الطهي. افرد الخضار المتبّلة في طبقة واحدة على الصينية. اشوها في الفرن المسخّن مسبقًا لمدة 15–20 دقيقة، أو حتى تنضج الخضار وتتكرمل قليلًا.","أخرج الصينية من الفرن وانثر السبانخ الصغيرة فوق الخضار المشوية. ستؤدي الحرارة إلى ذبول السبانخ قليلًا.","اصنع أربع حفر صغيرة بين الخضار واكسر بيضة برفق في كل حفرة.","أعد الصينية إلى الفرن واخبزها 7–10 دقائق إضافية، أو حتى يتماسك بياض البيض وتصل الصفار إلى درجة النضج التي تفضّلها.","رشّ الريحان الطازج فوق الخضار والبيض."],[],[])))
O.append(R(6567846,ar=(
"تبولة الكينوا",
"يمكن تقديم هذه السلطة فورًا، لكن الأفضل تحضيرها في اليوم السابق. لتبريد الكينوا بسرعة، افردها على صينية خَبز وضعها في الثلاجة حتى تبرد.",
"6","¾ كوب",
["1 كوب كينوا (جافة)","1½ كوب ماء","1 ملعقة كبيرة زيت زيتون بكر ممتاز","2 ملعقة كبيرة عصير ليمون (من حبة ليمون متوسطة)","1 ملعقة صغيرة قشر ليمون مبشور (من حبة ليمون متوسطة)","1 حبة طماطم متوسطة (مقطّعة مكعبات صغيرة جدًا)","1 حبة خيار متوسطة (منزوعة البذور ومقطّعة مكعبات صغيرة جدًا)","1 كوب بقدونس طازج (مفروم)","½ كوب نعناع طازج (مفروم)","½ ملعقة صغيرة ملح (اختياري)","¼ ملعقة صغيرة فلفل أسود"],
["اغسل الكينوا ثم اخلطها مع 1½ كوب من الماء. اتركها حتى تغلي ثم خفّض الحرارة لتغلي بهدوء. غطِّها واطبخها 15 دقيقة أو حتى يُمتص كل السائل. فكّكها بشوكة ثم اتركها حتى تبرد تمامًا.","اخلط الكينوا المبرّدة مع زيت الزيتون وقشر الليمون المبشور وعصير الليمون والطماطم والخيار والبقدونس والنعناع والملح (اختياري) والفلفل الأسود المطحون. ضعها في الثلاجة أو قدّمها."],[],[])))
O.append(R(6567916,
("Brochetas de albóndigas","Estas albóndigas son una comida divertida para toda la familia. O sírvalas en una fuente como aperitivo la próxima vez que tenga invitados.","6","2 brochetas",
["1 rocío, 0.25 gramos de aceite en aerosol antiadherente","4 claras de huevo grandes o 1 taza de sustituto de huevo","2 cucharadas de queso parmesano (rallado)","2 dientes de ajo (picados)","20 onzas de carne molida de pavo magra (93 % magra)","1/2 cucharadita de sal","1/4 de cucharadita de pimienta negra molida","12 palillos de bambú para brochetas","24 tomates uva o cherry","8 onzas de hongos cremini (baby bella) (cortados por la mitad si es necesario para obtener 12 piezas)","1 cebolla mediana (en cuartos, y cada cuarto cortado en tres partes (12 trozos de cebolla en total))","1/4 de taza de vinagre balsámico","1 cucharadita de aceite de oliva"],
["Precaliente el horno a 375° F. Rocíe una bandeja para hornear con aceite en aerosol. Reserve.","Mezcle las claras de huevo, el queso parmesano, el ajo, el pavo, la sal y la pimienta. Mezcle bien y forme 24 albóndigas. Refrigere las albóndigas por lo menos 30 minutos.","Ensarte en cada palillo, alternando, 2 albóndigas, 2 tomates, 1 pieza de hongo y 1 pieza de cebolla.","En un tazón pequeño, bata el vinagre y el aceite de oliva.","Coloque las brochetas en la bandeja para hornear y úntelas por todos lados con la mezcla de vinagre y aceite de oliva. Reserve el adobo.","Hornee las brochetas 10 minutos. Úntelas de nuevo por todos lados con el adobo y hornee de 10 a 15 minutos más. Las albóndigas deben cocinarse hasta alcanzar una temperatura interna de al menos 165° F."],[],[]),
("أسياخ الكرات اللحمية","تُعدّ هذه الكرات اللحمية وجبة ممتعة للعائلة. أو قدّمها على طبق كمقبلات في المرة القادمة التي تستضيف فيها ضيوفًا.","6","سيخان",
["1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","4 بياضات بيض كبيرة أو 1 كوب بديل البيض","2 ملعقة كبيرة جبن بارميزان (مبشور)","2 فص ثوم (مفروم)","20 أونصة لحم ديك رومي مفروم قليل الدسم (93% خالٍ من الدسم)","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود مطحون","12 سيخ خيزران","24 حبة طماطم عنبية أو كرزية","8 أونصات فطر كريميني (بيبي بيلا) (مقطّع إلى نصفين عند الحاجة للحصول على 12 قطعة)","1 حبة بصل متوسطة (مقطّعة أرباعًا، ثم يُقطَّع كل ربع إلى ثلاث قطع (12 قطعة بصل إجمالًا))","¼ كوب خل بلسمي","1 ملعقة صغيرة زيت زيتون"],
["سخّن الفرن مسبقًا على 375° فهرنهايت (190° مئوية). ادهن صينية خَبز ببخاخ الطهي. ضعها جانبًا.","اخلط بياض البيض والجبن البارميزان والثوم ولحم الديك الرومي والملح والفلفل. اخلطها جيدًا وشكّل 24 كرة لحم. ضع الكرات في الثلاجة 30 دقيقة على الأقل.","اغرس في كل سيخ، بالتناوب، كرتين من اللحم وحبتي طماطم وقطعة فطر واحدة وقطعة بصل واحدة.","في وعاء صغير، اخفق الخل مع زيت الزيتون.","ضع الأسياخ على صينية الخَبز ودهنها من جميع الجوانب بخليط الخل وزيت الزيتون. احتفظ بالتتبيلة المتبقية.","اخبز الأسياخ 10 دقائق. ادهنها من جميع الجوانب مرة أخرى بالتتبيلة واخبزها 10–15 دقيقة إضافية. يجب أن تنضج الكرات حتى تصل درجة حرارتها الداخلية إلى 165° فهرنهايت (75° مئوية) على الأقل."],[],[])))
O.append(R(6568402,
("Pan de maíz con alcaravea en sartén","NOTA: El pan también se puede preparar en un molde cuadrado de 8 pulgadas, rociado con aceite en aerosol antiadherente. En ese caso no necesitará las 2 cucharaditas de aceite vegetal.","16","1 porción triangular",
["1 cucharadita de semillas de alcaravea","1/4 de taza más 2 cucharaditas de aceite vegetal (divididas)","1 taza de harina de maíz","1 taza de harina integral","1 1/2 cucharaditas de polvo para hornear","1/2 cucharadita de bicarbonato de sodio","1/2 cucharadita de sal","2 huevos grandes","1 taza de suero de leche bajo en grasa","1/4 de taza de miel"],
["Precaliente el horno a 400° F. En una sartén pequeña y seca, tueste las semillas de alcaravea a fuego medio de 2 a 3 minutos, solo hasta que se doren ligeramente y desprendan su aroma; reserve. Cuando el horno esté caliente, agregue 2 cucharaditas del aceite vegetal a una sartén de hierro fundido de 9 pulgadas. Caliente la sartén en el horno durante 5 minutos.","Mientras tanto, en un tazón grande, mezcle la harina de maíz, la harina, el polvo para hornear, el bicarbonato de sodio, la sal y las semillas de alcaravea.","En otro tazón, bata los huevos con un batidor de alambre. Agregue el suero de leche, la miel y el 1/4 de taza de aceite vegetal.","Agregue los ingredientes húmedos a los ingredientes secos y mezcle hasta que se integren.","Con cuidado, vierta la masa en la sartén caliente y hornee de 20 a 22 minutos, o hasta que el pan de maíz esté cocido por completo y un probador de pasteles o un palillo insertado en el centro salga limpio. Deje enfriar el pan de maíz durante 5 minutos. Corte en 16 porciones triangulares del mismo tamaño y sirva caliente."],[],[]),
("خبز الذرة بالكراوية في المقلاة","ملاحظة: يمكن أيضًا تحضير الخبز في قالب خَبز مربّع مقاس 8 بوصات مدهون ببخاخ الطهي غير اللاصق. في هذه الحالة لن تحتاج إلى ملعقتين صغيرتين من الزيت النباتي.","16","1 قطعة مثلثة",
["1 ملعقة صغيرة بذور الكراوية","¼ كوب زائد 2 ملعقة صغيرة زيت نباتي (مقسّم)","1 كوب دقيق الذرة","1 كوب دقيق القمح الكامل","1½ ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصودا","½ ملعقة صغيرة ملح","2 بيضة كبيرة","1 كوب لبن رائب (بتيرميلك) قليل الدسم","¼ كوب عسل"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (200° مئوية). في مقلاة صغيرة جافة، حمّص بذور الكراوية على نار متوسطة 2–3 دقائق، حتى تكتسب لونًا ذهبيًا خفيفًا وتفوح رائحتها فقط؛ ضعها جانبًا. عندما يسخن الفرن، أضف ملعقتين صغيرتين من الزيت النباتي إلى مقلاة من الحديد الزهر مقاس 9 بوصات. سخّن المقلاة في الفرن لمدة 5 دقائق.","في الأثناء، في وعاء كبير، اخلط دقيق الذرة والدقيق وبيكنج باودر وبيكربونات الصودا والملح وبذور الكراوية.","في وعاء منفصل، اخفق البيض بمضرب سلكي. أضف اللبن الرائب والعسل و¼ كوب الزيت النباتي.","أضف المكوّنات السائلة إلى المكوّنات الجافة واخلطها حتى تمتزج فقط.","اسكب العجين بحذر في المقلاة الساخنة واخبزه 20–22 دقيقة، أو حتى ينضج خبز الذرة تمامًا ويخرج مسبار الكيك أو عود أسنان نظيفًا عند غرزه في الوسط. اترك خبز الذرة يبرد 5 دقائق. قطّعه إلى 16 قطعة مثلثة متساوية الحجم وقدّمه دافئًا."],[],[])))
O.append(R(6568654,ar=(
"يخنة قرع الجوز مع الحمص",
"تضم هذه اليخنة المشبعة قرع الجوز (باتر نت)، وهو نوع من القرع الشتوي يأتي موسمه في الأشهر الباردة من السنة. حضّرها في عطلة نهاية الأسبوع وخذ ما تبقّى منها كغداء خلال الأسبوع.",
"8","1 كوب",
["1 حبة قرع جوز متوسطة","2 ملعقة صغيرة زيت زيتون","1 حبة بصل كبيرة (مفرومة)","3 فص ثوم (مفروم)","½ رطل بطاطس حمراء (غير مقشّرة ومقطّعة أرباعًا)","1 كوب مرق دجاج قليل الصوديوم (قليل الدسم، مخفّض الصوديوم)","1 علبة (14 أونصة) طماطم معلّبة مقطّعة مكعبات (دون تصفية، جرّب الطماطم المشوية على النار لنكهة أقوى)","¾ ملعقة صغيرة أوريجانو مجفف","⅛ ملعقة صغيرة ملح كوشر","⅛ ملعقة صغيرة فلفل أسود مطحون طازجًا، حسب الرغبة","1 علبة (15 أونصة) حمص (مصفّى ومشطوف)","2 ملعقة كبيرة زبدة فول سوداني طبيعية كريمية (محرّكة جيدًا حتى تصبح ناعمة)","2 ملعقة كبيرة بقدونس (مفروم)"],
["حضّر قرع الجوز. ضع حبة القرع كاملة على الصحن الدوّار أو الرف داخل الميكروويف. سخّنها في الميكروويف 5 دقائق. أخرجها بحذر واتركها حتى تبرد بما يكفي للإمساك بها. بسكين حادة، اقطع القرع إلى نصفين بالعرض. قشّر كل نصف بالسكين مع القطع قريبًا من القشرة لإزالة القشرة فقط. اقطع كل نصف بالطول. أخرج البذور من النصف السفلي من القرع وتخلّص منها. قطّع كل القرع إلى مكعبات بطول 1 بوصة. ضعها جانبًا. تسهّل هذه الطريقة تقطيع قرع الجوز الصلب لأنها تساعد على تخفيف التصاق القشرة.","سخّن الزيت في قدر ثقيلة كبيرة على نار متوسطة. أضف البصل والثوم وقلّبهما 5–6 دقائق. أضف قرع الجوز والبطاطس وحرّك لتتغلف بالبصل والثوم. أضف المرق والطماطم مع عصيرها والأوريجانو والملح والفلفل. اتركها حتى تغلي. خفّض الحرارة لتغلي بهدوء، وغطِّ القدر واطبخ على نار متوسطة إلى منخفضة نحو 20 دقيقة، حتى يلين القرع والبطاطس. قد يصبح بعض القرع طريًا جدًا.","اخلط الحمص وزبدة الفول السوداني برفق واطبخ 5 دقائق. زيّن بالبقدونس المفروم."],[],[])))
O.append(R(6569048,
("Pizzas de repollo en bandeja con «salchicha» desmenuzada, pimientos y cebollas","Esta pizza de repollo, rica en verduras, sustituye la masa por rodajas de repollo asadas, con lo que se mantienen bajos los carbohidratos y se aporta sabor, proteína y verduras sin almidón. Una mezcla de requesón y queso mozzarella reducido en grasa aporta un sabor cremoso que se derrite. El «chorizo» de tofu desmenuzado agrega proteína vegetal sabrosa, y las cebollas y los pimientos asados aumentan la fibra y el contenido de verduras, por lo que es un plato principal vegetariano, amigable con la diabetes, abundante y satisfactorio. Se termina con un toque de aderezo ranch ácido de yogur griego sin grasa que agrega una cobertura cremosa y rica en proteína.","4","2 rodajas de repollo con coberturas + 2 cucharadas de salsa de yogur",
["1 repollo verde grande (unas 2 ½ libras, cortado en 8 rodajas de aproximadamente 3/8 de pulgada de grosor)","2 rocíos, 0.50 g de aceite de oliva en aerosol","1 lata (de 14 onzas) de tomates enteros en lata (sin sal añadida)","1 diente de ajo (picado)","1 cucharadita de orégano seco","1/2 cucharadita de pimienta negra","14 onzas de tofu extrafirme (prensado y desmenuzado)","1 cucharada de salsa de soya baja en sodio (o tamari)","1/4 de cucharadita de semillas de hinojo (machacadas)","1/4 de cucharadita de hojuelas de chile rojo machacado","1 cucharadita de ajo en polvo (dividida)","1/2 taza de requesón (sin grasa)","1/2 taza de queso mozzarella (reducido en grasa, rallado)","1 taza de pimientos (en rodajas)","1 taza de cebolla (amarilla o blanca, en rodajas finas)","1/3 de taza de hojas de albahaca fresca","1/2 taza de yogur griego natural sin grasa","1 cucharada de jugo de limón","1 cucharadita de eneldo seco","1/2 cucharadita de cebolla en polvo","1 cucharada de agua"],
["En un tazón mediano, triture los tomates con las manos o pulse ligeramente en una licuadora hasta que estén casi lisos. Agregue el ajo picado, ½ cucharadita del orégano y ¼ de cucharadita de la pimienta negra. Reserve.","Precaliente el horno a 425° F. Forre dos bandejas grandes para hornear con papel pergamino. Coloque las rodajas de repollo en una sola capa y rocíe ligeramente ambos lados con aceite en aerosol. Esparza los pimientos y las cebollas alrededor del repollo. Ase de 20 a 25 minutos, volteando el repollo a la mitad del tiempo, hasta que esté tierno y ligeramente dorado.","Mientras se asa el repollo, caliente una sartén seca a fuego medio. Agregue el tofu desmenuzado y cocine de 2 a 3 minutos para eliminar la humedad. Agregue la salsa de soya, las semillas de hinojo, el ajo en polvo, el ½ cucharadita restante de orégano, el ¼ de cucharadita restante de pimienta negra y las hojuelas de chile rojo. Cocine, revolviendo con frecuencia, hasta que esté ligeramente dorado y aromático, unos 8 a 10 minutos.","Bata el yogur griego sin grasa, el jugo de limón, el eneldo, el 1/2 cucharadita restante de ajo en polvo y la cebolla en polvo. Agregue el agua de a 1 cucharada a la vez hasta que el aderezo tenga una consistencia que se pueda verter. Reserve.","Saque las rodajas de repollo del horno. Ponga 3 cucharadas de salsa de tomate sobre cada rodaja. Distribuya uniformemente 2 cucharadas de requesón sin grasa sobre la salsa de cada rodaja y luego espolvoree las pizzas de manera uniforme con la mozzarella reducida en grasa. Cubra con el tofu desmenuzado, los pimientos y las cebollas. Vuelva a colocarlas en el horno y hornee de 10 a 15 minutos, hasta que el queso se derrita y todo esté caliente.","Deje enfriar las pizzas 5 minutos y luego esparza las hojas de albahaca por encima. Rocíe el ranch de yogur sobre cada pizza justo antes de servir. Sirva 2 rodajas de pizza de repollo por persona."],[],[]),
("بيتزا الملفوف على صينية الخَبز مع فتات «النقانق» والفلفل والبصل","تستبدل هذه البيتزا النباتية الغنية بالخضار العجينة بشرائح ملفوف مشوية، فتبقى الكربوهيدرات منخفضة مع الكثير من النكهة والبروتين والخضار غير النشوية. يمنح مزيج الجبن القريش وجبن الموزاريلا المخفض الدسم قوامًا كريميًا ذائبًا لذيذًا. ويضيف فتات «النقانق» المصنوع من التوفو بروتينًا نباتيًا شهيًا، بينما يزيد البصل والفلفل الرومي المشويان الألياف والخضار، فتصبح طبقًا رئيسيًا نباتيًا مناسبًا لمرضى السكري، مشبعًا ومُرضيًا. وتُختم بتتبيلة رانش منعشة من الزبادي اليوناني الخالي من الدسم تمنحها غطاءً كريميًا غنيًا بالبروتين.","4","شريحتا ملفوف مع الإضافات + ملعقتان كبيرتان من صلصة الزبادي",
["1 رأس ملفوف أخضر كبير (نحو 2½ رطل، مقطّع إلى 8 شرائح دائرية بسماكة نحو ⅜ بوصة)","2 بخّة (0.50 غ) بخاخ طهي بزيت الزيتون","1 علبة (14 أونصة) طماطم كاملة معلّبة (بدون ملح مضاف)","1 فص ثوم (مفروم)","1 ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة فلفل أسود","14 أونصة توفو شديد التماسك (مضغوط ومفتّت)","1 ملعقة كبيرة صلصة صويا قليلة الصوديوم (أو تاماري)","¼ ملعقة صغيرة بذور الشمر (مطحونة خشنًا)","¼ ملعقة صغيرة رقائق الفلفل الأحمر الحار المجروشة","1 ملعقة صغيرة مسحوق الثوم (مقسّمة)","½ كوب جبن قريش (خالٍ من الدسم)","½ كوب جبن موزاريلا (مخفّض الدسم، مبشور)","1 كوب فلفل رومي (مقطّع شرائح)","1 كوب بصل (أصفر أو أبيض، مقطّع شرائح رفيعة)","⅓ كوب أوراق ريحان طازجة","½ كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة شبت مجفف","½ ملعقة صغيرة مسحوق البصل","1 ملعقة كبيرة ماء"],
["في وعاء متوسط، اهرس الطماطم بيديك أو اخلطها بالخلاط بنبضات قصيرة حتى تصبح ناعمة في معظمها. أضف الثوم المفروم و½ ملعقة صغيرة من الأوريجانو و¼ ملعقة صغيرة من الفلفل الأسود وقلّب. ضعها جانبًا.","سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية). بطّن صينيتي خَبز كبيرتين بورق الزبدة. رتّب شرائح الملفوف في طبقة واحدة ورشّ الوجهين بخفة ببخاخ الطهي. وزّع الفلفل الرومي والبصل حول الملفوف. اشوِ 20–25 دقيقة مع قلب الملفوف في منتصف المدة، حتى يلين ويكتسب لونًا بنيًّا خفيفًا.","بينما يُشوى الملفوف، سخّن مقلاة جافة على نار متوسطة. أضف التوفو المفتّت واطبخه 2–3 دقائق لإخراج الرطوبة. أضف صلصة الصويا وبذور الشمر ومسحوق الثوم و½ ملعقة صغيرة المتبقية من الأوريجانو و¼ ملعقة صغيرة المتبقية من الفلفل الأسود ورقائق الفلفل الأحمر الحار. اطبخ مع التقليب المتكرر حتى يكتسب لونًا بنيًّا خفيفًا وتفوح رائحته، نحو 8–10 دقائق.","اخفق الزبادي اليوناني الخالي من الدسم وعصير الليمون والشبت و½ ملعقة صغيرة المتبقية من مسحوق الثوم ومسحوق البصل. أضف الماء ملعقة كبيرة في كل مرة حتى تصل التتبيلة إلى قوام يمكن سكبه. ضعها جانبًا.","أخرج شرائح الملفوف من الفرن. ضع 3 ملاعق كبيرة من صلصة الطماطم على كل شريحة. وزّع ملعقتين كبيرتين من الجبن القريش الخالي من الدسم بالتساوي فوق الصلصة على كل شريحة، ثم رشّ البيتزا بالتساوي بجبن الموزاريلا المخفض الدسم. ضع فوقها فتات التوفو والفلفل والبصل. أعدها إلى الفرن واخبزها 10–15 دقيقة، حتى يذوب الجبن وتسخن المكوّنات جميعها.","اترك البيتزا تبرد 5 دقائق ثم انثر أوراق الريحان فوقها. رشّ رانش الزبادي فوق كل بيتزا قبل التقديم مباشرة. قدّم شريحتين من بيتزا الملفوف لكل شخص."],[],[])))
O.append(R(6569922,
("Lentejas cocidas","Información nutricional de las lentejas cocidas","1","1/2 taza cocida",
["1/2 taza de lentejas cocidas (use 1/4 de taza secas)"],[],[],[]),
("عدس مطبوخ","المعلومات الغذائية للعدس المطبوخ","1","½ كوب مطبوخ",
["½ كوب عدس مطبوخ (استخدم ¼ كوب جاف)"],[],[],[])))
O.append(R(6570315,ar=(
"قوارب الكوسا المحشوة بالبروسكيتا",
"يُفضَّل أن تملأ نصف طبقك بالخضار غير النشوية، وهذا يعني أن عليك الإبداع حتى لا تشعر بالملل من الوصفات نفسها. قوارب الكوسا هذه سريعة وسهلة وتغيير لذيذ عن الخضار المطهوة على البخار.",
"4","½ حبة كوسا",
["2 حبة كوسا كبيرة","2 ملعقة صغيرة زيت زيتون","⅛ ملعقة صغيرة فلفل أسود","½ كوب بروسكيتا جاهزة (في برطمان)","4 ملاعق صغيرة جبن بارميزان (مبشور)"],
["اقطع طرفي الكوسا وتخلّص منهما. اقطع كل حبة كوسا إلى نصفين بالطول.","استخدم ملعقة لتفريغ وسط الكوسا مع ترك قاعدة رقيقة في الأسفل ليمكن حشو «القارب». ضع اللب المفرّغ في وعاء صغير؛ وضعه جانبًا.","اغلِ قدرًا متوسطة من الماء المملح. اسلق قوارب الكوسا إلى أن تبدأ بالليونة فقط، نحو 2–3 دقائق. ضع قوارب الكوسا فورًا في وعاء من الماء المثلج. صفِّ الكوسا وضعها على صينية خَبز.","سخّن زيت الزيتون في مقلاة متوسطة على نار متوسطة. رشّ خليط الكوسا المحتفظ به بالفلفل الأسود؛ أضفه إلى المقلاة وقلّبه نحو 6–8 دقائق. أضف البروسكيتا وقلّب؛ خفّض الحرارة واتركه على نار هادئة 3 دقائق.","املأ قوارب الكوسا الأربعة بخليط البروسكيتا بالتساوي بالملعقة. رشّ كل قارب كوسا بملعقة صغيرة واحدة من جبن البارميزان.","شغّل الشواية العلوية للفرن. اشوِ قوارب الكوسا المحشوة حتى تكتسب لونًا ذهبيًا خفيفًا، نحو 2–3 دقائق؛ راقبها عن كثب كي لا تحترق."],[],[])))
O.append(R(6571015,ar=(
"شوربة كريمية بالدجاج والذرة والهالابينو",
"هذه الشوربة الكريمية الغنية الصالحة كطبق رئيسي مليئة بالقطع الشهية، ومنها الذرة الحلوة والدجاج الغني بالعصارة. يمنحها فلفل الهالابينو لمسة من الحرارة الحارة. قدّمها مع سلطة جرجير خفيفة وحصة من البطيخ الطازج، أو مع سلطة البطيخ والجرجير والفيتا، لوجبة صيفية مثالية.",
"8","1¼ كوب",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل أصفر متوسطة (مقشّرة ومفرومة)","2 جزرة متوسطة (مقشّرة ومفرومة)","2 عود كرفس (مفروم)","2 حبة فلفل هالابينو متوسطة (منزوعة البذور ومفرومة)","2 فص ثوم (مقشّر ومهروس)","4 كيزان ذرة حلوة متوسطة (تُقطع الحبوب عن الكوز، أو 4 أكواب حبوب مجمّدة مذابة ومصفّاة)","1 ملعقة كبيرة بهارات خالية من الملح","½ ملعقة صغيرة فلفل أسود","4 أكواب مرق دجاج خالٍ من الدسم وقليل الصوديوم","2 كوب صدر دجاج مطبوخ (مفروم)","1 كوب زبادي يوناني سادة خالٍ من الدسم"],
["سخّن الزيت في قدر شوربة كبيرة على نار متوسطة. أضف البصل والجزر والكرفس والهالابينو والثوم والذرة وقلّبها 5 إلى 7 دقائق.","أضف البهارات الخالية من الملح والفلفل الأسود ومرق الدجاج. اتركها حتى تغلي، ثم خفّض الحرارة واتركها تغلي بهدوء مع التغطية لمدة 20 دقيقة.","ارفع القدر عن النار وهرس نحو نصف الشوربة باستخدام خلاط يدوي أو خلاط عادي. إذا استخدمت الخلاط العادي، فاهرسها على دفعات وتأكد من عدم ملء الخلاط أكثر من اللازم. أعد المهروس إلى القدر.","أضف الدجاج وسخّنه جيدًا. ارفع القدر عن النار.","أضف الزبادي وقلّب وقدّم. لا تغلِ الشوربة بعد إضافة الزبادي."],[],[])))
O.append(R(6571661,
("Estofado de frijoles rojos","Los frijoles son un alimento básico de la cocina latina: frijoles negros cubanos, frijoles pintos refritos mexicanos, etc. Estos frijoles rojos son populares en la cocina puertorriqueña y dominicana.","6","1/2 taza",
["1 cucharada de aceite de oliva","1 cebolla mediana (finamente picada)","1 pimiento rojo grande (en cubos)","2 dientes de ajo (picados)","1 taza (unas 7 onzas) de calabaza pelada y en cubos, o calabaza de Castilla","1 lata (de 15.5 onzas) de frijoles rojos sin sal añadida (enjuagados y escurridos)","1 1/2 tazas de caldo de pollo sin sal","1/4 de taza de salsa de tomate sin sal añadida","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra","1/4 de taza de cilantro picado"],
["Caliente el aceite en una sartén grande antiadherente a fuego medio-alto. Agregue la cebolla, el pimiento y el ajo, y cocine, revolviendo de vez en cuando, hasta que las verduras estén tiernas, unos 8 minutos.","Agregue la calabaza, los frijoles, el caldo, la salsa de tomate, la sal y la pimienta y deje que hierva. Reduzca el fuego a medio. Tape y cocine hasta que la calabaza esté tierna, de 10 a 12 minutos. Agregue el cilantro y revuelva."],[],[]),
("يخنة الفاصولياء الحمراء","الفاصولياء من المكوّنات الأساسية في المطبخ اللاتيني: الفاصولياء السوداء الكوبية، والفاصولياء البينتو المقلية المكسيكية، وغيرها. وتشتهر هذه الفاصولياء الحمراء في المطبخين البورتوريكي والدومينيكاني.","6","½ كوب",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل متوسطة (مفرومة ناعمًا)","1 حبة فلفل رومي أحمر كبيرة (مقطّعة مكعبات)","2 فص ثوم (مفروم)","1 كوب (نحو 7 أونصات) يقطين أو قرع جوز مقشّر ومقطّع مكعبات","1 علبة (15.5 أونصة) فاصولياء حمراء بدون ملح مضاف (مشطوفة ومصفّاة)","1½ كوب مرق دجاج غير مملح","¼ كوب صلصة طماطم بدون ملح مضاف","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","¼ كوب كزبرة خضراء مفرومة"],
["سخّن الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. أضف البصل والفلفل الرومي والثوم، واطبخ مع التقليب من حين لآخر حتى تنضج الخضار، نحو 8 دقائق.","أضف اليقطين والفاصولياء والمرق وصلصة الطماطم والملح والفلفل واتركها حتى تغلي. خفّض الحرارة إلى متوسطة. غطِّ المقلاة واطبخ حتى يلين اليقطين، 10–12 دقيقة. أضف الكزبرة الخضراء وقلّب."],[],[])))
